return ['domain'=>'tranzly','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'mn','project-id-version'=>'tranzly','pot-creation-date'=>'2026-09-26T13:56:07+00:00','po-revision-date'=>'2026-09-26T13:56:07+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Tranzly'=>'Tranzly','https://zinndigital.com/wordpress-plugins/tranzly'=>'https://zinndigital.com/wordpress-plugins/tranzly','Multilingual WordPress, one post per language: linked translations of posts, pages, categories, media text, widgets and the site title, with your old Tranzly translations imported.'=>'Олон хэл дээрх WordPress, хэл тус бүрд нэг нийтлэл: нийтлэл, хуудас, ангилал, медиа текст, виджет болон сайтын гарчиг хоорондын холбоотой орчуулгууд, үүнд таны хуучин Tranzly орчуулгууд импортлогдсон болно.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'AI үйлчилгээ үзүүлэгчид','The makers of ChatGPT. A good all-rounder.'=>'ChatGPT-g бүтээгчид. Сайн бүх талын үйлчилгээтэй.','The makers of Claude. Strong at writing and careful reasoning.'=>'Claude-г бүтээгчид. Бичих болон нарийн үндэслэл гаргахдаа сайчууд.','Google\'s Gemini models. Fast and inexpensive.'=>'Google-ийн Gemini загvуд. Хурдан бөгөөд хямд.','A European AI company with fast, inexpensive models.'=>'Хурдан бөгөөд хямд загваруудтай Европын хиймэл оюун ухааны компани.','Low-cost models that are good at writing and code.'=>'Бичих болон код бичихэд сайн, хямд өртөгтэй загварууд.','One key for models from many different providers.'=>'Олон өөр үйлчилгээ үзүүлэгчийн загваруудад зориулсан нэг түлхүүр.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Өөрийн компьютер эсвэл сервер дээр ажиллаж буй загварыг оролцуулаад OpenAI-ийн API шиг ажилладаг аливаа үйлчилгээ.','General (used when nothing more specific is set)'=>'Ерөнхий (илүү тодорхой утга тохируулаагүй үед хэрэглэнэ)','Writing and rewriting'=>'Бичиж болон дахин бичиж байна','Translation'=>'Оrчуулга','Code and CSS'=>'Код ба CSS','Sorry, you are not allowed to access this page.'=>'Уучлаарай, та энэ хуудсанд хандах эрхгүй байна.','These settings are shared by every plugin that uses them: %s.'=>'Эдгээр тохиргоог дараах залгаасууд дундаа ашигладаг: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Таны түлхүүрүүд энэ сайтын өгөгдлийн санд шифрлэгдсэн бөгөөд зөвхөн таны сонгосон үйлчилгээ үзүүлэгч рүү л илгээгдэх ба бидэнд хэзээ ч ирдэггүй.','Step 1 of 2: choose an AI provider'=>'Алхам 1 / 2: AI нийлүүлэгчийг сонгоно уу','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Та өөрийн түлхүүрээ авчрах тул ашигласан зүйлийнхээ төлбөрийг үйлчилгээ үзүүлэгчид шууд төлнө. Эргэлзэж байна уу? Эдгээрийн аль нь ч сайн ажиллах бөгөөд та дараа нь илүүг нэмж болно.','Next'=>'Дараагийнх','Step 2 of 2: connect %s'=>'2/2-р алхам: %s-г холбох','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'OpenAI-compatible үйлчилгээнийхээ хаягийг /v1 гэж төгсгөн оруулна уу. Түлхүүр нь зөвхөн үйлчилгээ шаардсан үед л хэрэгтэй.','Open %s and sign in (or create a free account).'=>'%s-ийг нээж, нэвтэрнэ үү (эсвэл үнэгүй бүртгэл үүсгэнэ үү).','the %s API keys page'=>'%s API түлхүүрийн хуудас','Create a new key and copy it.'=>'Шинэ түлхүүр үүсгээд хуулж авна уу.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Үүнийг доор буулгаж, "Хадгалж шалгах" дээр дарна уу. Энэ нь ажиллаж байгаа эсэхийг шалгахын тулд бид нэг жижиг хүсэлт илгээдэг.','Most providers need a little credit on the account before a key works: %s.'=>'Ихэнх үйлчилгээ үзүүлэгчдэд түлхүүр ажиллахаас өмнө дансанд бага зэрэг үлдэгдэл шаардлагатай байдаг: %s.','add credit'=>'Кредит нэмэх','← Choose a different provider'=>'← Өөр үйлчилгээ үзүүлэгч сонгох','Address'=>'Хаяг','Saved key ends in …%s — paste a new one to replace it'=>'Хадгалсан түлхүүр …%s гэж төгссөн байна — солихын тулд шинийг буулгана уу','Key (optional)'=>'Түлхүүр (заавал биш)','API key'=>'API түлхүүр','Save and test'=>'Хадгалж шалгах','Providers'=>'Үйлчилгээ үзүүлэгчид','Provider'=>'Үйлчилгээ үзүүлэгч','Status'=>'Төлөв','Key'=>'Түлхүүр','Get a key'=>'Түлхүүр авах','Test'=>'Тест','Remove'=>'Устгах','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Залгаас илүү шинэ хувилбараар хадгалагдсан байна: энэ залгаасыг шинэчлэх эсвэл түлхүүрийг дахин оруулна уу.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Хадгалсан түлхүүрийг цаашид нээх боломжгүй (сайтны аюулгүй байдлын түлхүүрүүд өөрчлөгдсөн). Үүнийг дахин оруулна уу.','Not connected'=>'Холбогдоогүй','Connected — last test passed %s'=>'Холбогдсон — сүүлийн тест амжилттай болсон %s','Last test failed: %s'=>'Сүүлийн тест амжилтгүй болсон: %s','Connected — not tested yet'=>'Холбогдсон — хараахан шалгаагүй байна','Which model to use'=>'Аль загварыг ашиглах вэ','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ нь тухайн үүрэгт бидний санал болгож буй загварыг илтгэнэ. Энэ жагсаалтад таны түлхүүрийн ашиглаж болох бүх загвар багтсан бөгөөд үйлчилгээ үзүүлэгчээс шууд мэдээллийг татаж авдаг.','— Recommended for the provider —'=>'— Үйлчилгээ үзүүлэгчид санал болгох —','Save models'=>'Загваруудыг хадгалах','Refresh the model lists from the providers'=>'Үйлчилгээ үзүүлэгчдээс загварын жагсаалтыг шинэчлэх','best quality'=>'хамгийн өндөр чанар','lowest cost'=>'хамгийн хямд','fastest'=>'хамгийн хурдан','Add a model yourself'=>'Загварыг өөрөө нэмэх','A model came out today? Paste its exact name to use it straight away.'=>'Шинэ загвар өнөөдөр гарсан уу? Шууд ашиглахын тулд яг тэр нэрийг нь буулгаад наана уу.','Model name'=>'Загварын нэр','Add model'=>'За загвар нэмэх','Recommended models list'=>'Санал болгож буй загваруудын жагсаалт','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Санал болгож буй загваруудын жагсаалтыг баталгаажуулж чадсангүй, тиймээс ямар нэгэн зөвлөмж харуулахгүй байна. Залгаасыг дахин суулгах эсвэл доорх өдөр тутмын шинэчлэлтийг идэвхжүүлнэ үү.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Ашиглаж буй жагсаалт %s-нд нийтлэгдсэн. Залгаас бүрийн шинэчлэлт шинийг авчирдаг.','Also check Zinn Digital® once a day for an updated list.'=>'Шинэчлэгдсэн жагсаалтыг авахын тулд Zinn Digital®-ийг өдөрт нэг удаа шалгана уу.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Зөвхөн энгийн татаж авах хүсэлтийг илгээдэг: түлхүүр байхгүй, сайтын хаяг байхгүй, таны агуулгын тухай юу ч байхгүй. Жагсаалтад гарын үсэг зурсан байх ба гарын үсгийн шалгалтанд тэнцээгүй жагсаалтыг хэрэгсэхгүй орхино.','Last checked %1$s: %2$s.'=>'Сүүлчийн шалгалт %1$s: %2$s.','Save, and check now if turned on'=>'Хадгалаад, идэвхжүүлсэн эсэхийг одоо шалгана уу','a newer list was installed'=>'шинэ жагсаалтыг суулгасан байна','already up to date'=>'аль хэдийн шинэчлэгдсэн','the download failed the signature check and was ignored'=>'татаж авсан файл гарын үсгийн шалгалтад тэнцээгүй тул алгаслаа','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital®-тэй холбогдож чадсангүй; одоогийн жагсаалт хэвээр үлдэнэ','turned off'=>'унтраасан','Open'=>'Нээх','Check their status page'=>'Тэдний төлөв байдлын хуудсыг шалгах','Open your billing page'=>'Таны төлбөр тооцооны хуудсыг нээх','Open your API keys page'=>'API түлхүүрийн хуудсаа нээх','Open the AI settings'=>'AI тохиргоог нээх','Sorry, you are not allowed to do that.'=>'Уучлаарай, танд үүнийг хийх зөвшөөрөл байхгүй байна.','Unknown provider.'=>'Үл мэдэгдэх үйлчилгээ үзүүлэгч.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Үйлчилгээнийхээ хаягийг оруулна уу, жишээ нь http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Энэ API түлхүүр шиг харагдахгүй байна. Зай авахгүйгээр дахин хуулж авна уу.','Paste your API key first.'=>'Эхлээд API түлхүүрээ оруулна уу.','Key removed.'=>'Түлхүүрийг устгалаа.','Models saved.'=>'Загваруудыг хадгалав.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'За загварын яг бүтэн нэрийг оруулна уу, жишээ нь үйлчилгээ үзүүлэгчийн баримт бичигт бичсэнтэй адил.','Added %s. Choose it under "Which model to use".'=>'%s нэмэгдлээ. "Аль загварыг ашиглах вэ" хэсгээс үүнийг сонгоно уу.','Model removed.'=>'Загварыг устгасан.','Daily updates are off. The list that came with the plugin is used.'=>'Өдөр тутмын шинэчлэлт унтраалттай байна. Плүгинтэй хамт ирсэн жагсаалтыг ашиглаж байна.','Checked: %s.'=>'Шалгасан: %s.','Model lists refreshed.'=>'За загварын жагсаалт шинэчлэгдлээ.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Таны AI түлхүүрийг зарим залгаасын шинэ хувилбараар хадгалсан байна. Энэ залгаасыг шинэчлэх эсвэл AI тохиргоонд түлхүүрээ дахин оруулна уу.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Таны хадгалсан AI түлхүүрийг цаашид нээх боломжгүй (сайтын аюулгүй байдлын түлхүүрүүд өөрчлөгдсөн байна). AI тохиргоонд үүнийг дахин оруулна уу.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI тохируулагдаагүй байна. AI тохиргоо хэсгээс AI үйлчилгээ үзүүлэгчийн түлхүүрийг нэмнэ үү.','No model is chosen for this task. Pick one in the AI settings.'=>'Энэ даалгаварт ямар ч загвар сонгогдоогүй байна. AI тохиргооноос нэгийг сонгоно уу.','That AI provider is not supported by this version of the plugin.'=>'Энэхүү загварын хувилбарт уг хиймэл оюун ухааны үйлчилгээ үзүүлэгчийг дэмжихгүй байна.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Энэ сайт таны хиймэл оюун ухааны үйлчилгээнд холбогдож чадсангүй. Энэ нь ажиллаж байгаа эсэх, мөн түүний хаяг вэб сервэрээс холбогдох боломжтой эсэхийг шалгана уу (өөрийн компьютер дээрх үйлчилгээ нь байршуулсан сайтаас холбогдох боломжгүй).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Энэ сайт %s руу холбогдож чадсангүй. Тэдний төлөв байдлын хуудсыг шалгана уу; хэрэв тэд ажиллаж байгаа бол таны вэб хост гадагш чиглэсэн холболтыг хаасан эсвэл хаяг буруу байж магадгүй юм.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s таны дансанд үлдэгдэл эсвэл эрх байхгүй байна гэж мэдэгдлээ. Тэдний систем дэх дансдаа үлдэгдэл нэмэх эсвэл лимитээ өсгөөд дахин оролдоно уу.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s таны түлхүүрийг зөвшөөрсөнгүй. Үсэг алдаж бичсэн, хүчингүй болгосон эсвэл хугацаа нь дууссан байж магадгүй. Шинэ түлхүүр үүсгээд энд буулгана уу.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s таны түлхүүрт хийсэн энэ хүсэлтийг зөвшөөрсөнгүй. Түлхүүр нь энэ загвар эсвэл функцэд хандах эрхгүй байж магадгүй, эсвэл таны дансыг баталгаажуулах шаардлагатай байна.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'%1$s загвар нь таны түлхүүрээр %2$s-с авах боломжгүй байна. AI тохиргооноос өөр загвар сонгоно уу.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Таны %2$s багцт "%1$s" загвар ороогүй байна. Хиймэл оюун ухааны тохиргооноос өөр загвар сонгох эсвэл багцаа шинэчлэнэ үү.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s нь таны түлхүүр хүсэлт илгээх хурдыг хязгаарлаж байна. Нэг минут хүлээгээд дахин оролцоно уу, эсвэл тэдэнтэй холбогдож хурдны хязгаарлалтаа өсүүлнэ үү.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s дээр одоогоор асуудал гарч байна (тэдний талаас тасалдал эсвэл ачаалал хэтэрсэн). Таны тохиргоонд ямар нэгэн асуудал байхгүй. Удахгүй дахин оролдоно уу.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'AI хүсэлт ямар шалтгаанаар бүтэлгүйтсэнийг тодорхойлох боломжгүй байна. Дахин оролдоно уу; хэрэв энэ байдал давтагдвал доорх дэлгэрэнгүй мэдээллийн хамт тусламжийн төвтэй холбогдоно уу.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'AI үйлчилгээ үзүүлэгч энэ залгаас унших боломжгүй хэлбэрээр хариуллаа. Дахин оролдоно уу; хэрэв энэ байдал давтагдвал өөр загвар сонгох эсвэл дэмжлэг үзүүлэх багтай холбогдоно уу.','Custom (OpenAI-compatible)'=>'Өөрийн (OpenAI-тай нийцэх)','Save a key for this provider first.'=>'Энэ үйлчилгээ үзүүлэгчийн түлхүүрийг эхлээд хадгална уу.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Таны түлхүүр ажиллаж байна, гэхдээ үйлчилгээ үзүүлэгч үүнд ямар нэгэн текст загвар жагсаагаагүй байна. Доор өөрөө загвар нэмнэ үү.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Холбогдсон. %1$s нь %2$s ашиглан хариуллаа. Таны хиймэл оюун ухааны функцууд ашиглахад бэлэн боллоо.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Таны хэрэглэгчийн эрх энэ сайт дээр хиймэл оюун ухаан ашиглахыг зөвшөөрөхгүй байна. Администратортой холбогдоно уу.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Энэ сайт сарын хиймэл оюун ухааны зарцуулалтын хязгаартаа хүрсэн байна. Админ үүнийг Хиймэл оюун ухааны тохиргооноос нэмэгдүүлэх боломжтой.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Энэ сайт хиймэл оюун ухааны хүсэлтийн сарын хязгаартаа хүрсэн байна. Администратор үүнийг Хиймэл оюун ухааны тохиргоонд өөрчилж нэмэгдүүлэх боломжтой.','Usage and cost'=>'Хэрэглээ ба зардал','The log, limits and role permissions apply to AI used through: %s.'=>'Лог, хязгаарлалт болон үүргийн зөвшөөрлүүд нь %s-ээр дамжуулан ашиглагдах хиймэл оюун ухаанд үйлчилнэ.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Зардал нь нийтлэгдсэн үнээс тооцоолсон ойролцоо дүнтэй бөгөөд үнэ нь тодорхойгүй загварыг тэг гэж үзнэ.','This month: %1$s requests, about %2$s.'=>'Энэ сар: %1$s хүсэлт, ойролцоогоор %2$s.','When'=>'Хэзээ','Who'=>'Хэн','Used for'=>'Ашиглагдсан зорилго','Model'=>'За загвар','Tokens in / out'=>'Орох / Гарах токены','About'=>'Тухай','Result'=>'Үр дүн','No AI requests have been made yet.'=>'AI хүсэлт хараахан хийгдээгүй байна.','Done'=>'Дууссан','Limits and permissions'=>'Хязгаарлалт болон зөвшөөрлүүд','Monthly spending limit (US dollars)'=>'Сараас сард зарцуулах дээд хязгаар (US доллар)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Ямар ч хязгаарлалт байхгүй бол хоосон үлдээгээрэй. Ойролцоо өртөг нь энэ хязгаарт хүрснээр хиймэл оюун ухаан тухайн сарын үлдэгдэл хугацаанд зогсоно.','Monthly request limit'=>'Сараас сард гарах хүсэлтийн хязгаар','Leave empty for no limit.'=>'Хязгааргүй бол хоосон үлдээгээрэй.','Who may use AI'=>'Хэн хиймэл оюун ухаан ашиглаж болох вэ','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Плүгрэгчийн боломжуудыг ашиглаж чадах бүх хүнд хиймэл оюун ухааныг ашиглах эрх олгохын тулд юуг ч бүү сонго. Админууд үүнийг үргэлж ашиглах боломжтой.','Save limits and permissions'=>'Хязгаар болон зөвшөөрлийг хадгалах','Limits and permissions saved.'=>'Хязгаар болон зөвшөөрлүүдийг хадчихав.','That language is not one of this site\'s languages.'=>'Энэ хэл нь энэ сайтын хэл биш байна.','A translation must be the same kind of content as the original.'=>'Орчуулга нь эх хувьтайгаа ижил төрлийн контент байх ёстой.','Choose one of the site\'s other languages.'=>'Site-ийн бусад хэлнүүдийн нэгийг сонгоно уу.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Энэхүү плагины хувилбарт админ дэлгэцийн скриптүүд байхгүй байна. Үүнийг албан ёсны багц ашиглан дахин суулгана уу.','This screen needs JavaScript.'=>'Энэ дэлгэцэнд JavaScript шаардлагатай.','Choose a language'=>'Хэл сонгох','Upgrade'=>'Шинэчлэх','Pricing'=>'Үнэ тариф','Start Trial'=>'Туршилтыг эхлүүлэх','Account'=>'Данс','Contact Us'=>'Бидэнтэй холбогдох','Affiliation'=>'Харyаллагa','the kind of softwarePlugin'=>'Плегин','greetingHey %s,'=>'Сайн байна уу %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Аюулгүй байдал болон функцийн шинэчлэлтүүд, боловсролын контент, зарим нэг санал болготуудын талаар имэйл мэдэгдэл хүлээн авах, мөн үндсэн WordPress орчны мэдээллийг хуваалцахын тулд бүртгүүлнэ үү. Энэ нь бидэнд %s-ийг таны сайттай илүү нийцтэй болгоход болон таны хэрэгцээг илүү сайн хангахад туслах болно.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Аюулгүй байдал болон функцийн шинэчлэлт, боловсролын контент, зарим үеийн санал болготуудын талаарх имэйл мэдэгдлийг хүлээн авч, WordPress орчны зарим үндсэн мэдээллийг хуваалцахын тулд бүртгүүлнэ үү.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Хэрэү та үүнийг алгасвал зүгээр ээ! %1$s ямар ч асуудалгүйгээр хэвийн ажиллах болно.','Allow & Continue'=>'Зөвшөөрөх ба үргэлжлүүлэх','verbSkip'=>'Алгасах','Skipping, please wait'=>'Алгасаж байна, хүлээнэ үү','Continue'=>'Үргэлжлүүлэх','Please wait'=>'Түр хүлээнэ үү','as activating pluginActivating'=>'Идэвхжүүлж байна','This will allow %s to'=>'Энэ нь %s-д дараах боломжийг олгоно:','Privacy Policy'=>'Нууцлалын бодлого','Terms of Service'=>'Үйлчилгээний нөхцөл','License Agreement'=>'Лицензийн гэрээ','Have a license key?'=>'Лиценз түлхүүр байна уу?','Activate License'=>'Лиценз идэвхжүүлэх','View Basic Profile Info'=>'Үндсэн профайл мэдээллийг үзэх','Your WordPress user\'s: first & last name, and email address'=>'Таны WordPress хэрэглэгчийн: овог, нэр болон имэйл хаяг','View Basic Website Info'=>'Вебсайтын үндсэн мэдээллийг харах','Homepage URL & title, WP & PHP versions, and site language'=>'Нүүр хуудасны URL болон гарчиг, WP болон PHP-ийн хувилбарууд, мөн сайтын хэл','View Basic %s Info'=>'Үндсэн %s мэдээллийг харах','Current %s & SDK versions, and if active or uninstalled'=>'Одоогийн %s & SDK хувилбарууд, мөн идэвхтэй эсвэл устгагдсан эсэх','Newsletter'=>'Мэдээний хуудас','Updates, announcements, marketing, no spam'=>'Шинэчлэлтүүд, зарлалууд, маркетинг, спам байхгүй','View Diagnostic Info'=>'Диагностик мэдээллийг үзэх','WordPress & PHP versions, site language & title'=>'WordPress & PHP хувилбарууд, сайтын хэл & гарчиг','View Plugins & Themes List'=>'Залгаас болон загваруудын жагсаалтыг харах','Names, slugs, versions, and if active or not'=>'Нэр, хаягийн өргөтгөл, хувилбар болон идэвхтэй эсэх','optional'=>'заавал биш','Never miss an important update'=>'Чухал шинэчлэлийг хэзээ ч бүү алдаарай','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Чухал шинэчлэлийг хэзээ ч алдахгүй байх, мөн %s-г таны сайттай илүү нийцтэй, таны хэрэгцээнд илүү сайн нийцдэг болгоход бидэнд туслах үүднээс бид энэхүү зөвшөөрлийн тохиргоог нэвтрүүлсэн болно.','Thank you for updating to %1$s v%2$s!'=>'%1$s v%2$s руу шинэчилсэнд баярлалаа!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Уfфикс нь 1-ээс 8 хүртэлх жижиг үсэг эсвэл тооноос бүрдсэн, үсгээр эхэлсэн байх ёстой бөгөөд залгаасыг нэрлэж болохгүй.','"%s" is not a language code. Use a WordPress locale such as fr_FR or de_DE.'=>'"%s" нь хэлний код биш байна. fr_FR эсвэл de_DE гэх мэт WordPress локал ашиглана уу.','List at least one language.'=>'Дояад таot нэг хэл жагсаана уу.','You are not allowed to translate this item.'=>'Энэ зүйлийг орчуулахыг хориглоно.','This item already has a version in that language.'=>'Энэ зүйл уг хэл дээр хэдийнэ хувилбартай байна.','The value for %s is not one of the allowed choices.'=>'%s-ийн утга зөвшөөрөгдсөн сонголтуудын нэг биш байна.','This item\'s group already has a %1$s version (#%2$d).'=>'Энэ зүйлийн бүлэг аль хэдийн %1$s хувилбартай байна (#%2$d).','An item cannot be its own translation.'=>'Эд зүйл өөрийнхөө орчуулга байж болохгүй.','That item is already a translation of something else. Unlink it first.'=>'Энэ зүйл аль хэдийн өөр зүйлийн орчуулга байна. Эхлээд холбоосыг нь салгана уу.','The translation link could not be saved.'=>'Орчуулгын холбоосыг хадгалж чадсангүй.','That text cannot be translated here.'=>'Энэ текстийг энд орчуулах боломжгүй байна.','That media text cannot be translated here.'=>'Энэ медиа текстийг энд орчуулах боломжгүй байна.','A translation can be published or kept as a draft.'=>'Орчуулгыг нийтлэх эсвэл ноорог хэлбэрээр хадгалах боломжтой.','You are not allowed to publish this kind of content.'=>'Та энэ төрлийн контентыг нийтлэхийг хориглоно.','This item is already written in that language.'=>'Энэ зүйл аль хэдийн тухайн хэл дээр бичигдсэн байна.','You are not allowed to change that translation.'=>'Та энэ орчуулгыг өөрчлөх эрхгүй байна.','This translation was edited by a person (or imported), so it is protected. Unlock it to translate it again.'=>'Энэ орчуулгыг хүн зассан (эсвэл импортолсон) тул хамгаалагдсан байна. Дахин орчуулахын тулд түгжээг нь тайлна уу.','No translation engine is set up yet. Add a key for one in Tranzly → Engines.'=>'Орчуулгын систем тохируулаагүй байна. Tranzly → Engines хэсгээс нэгийд нь түлхүүр нэмнэ үү.','That translation engine is not available on this site.'=>'Энэ сайт дээр уг орчуулгын систем байхгүй байна.','That translation engine is not set up yet: add its key first.'=>'Энэ орчуулгын систем хараахан тохируулагдаагүй байна: эхлээд түүний түлхүүрийг нэмнэ үү.','%s did not return a translation for every part of this item. Nothing was changed.'=>'%s нь энэ зүйлийн бүх хэсэгт орчуулга буцаасангүй. Юу ч өөрчлөгдөөгүй.','An engine id must be lowercase letters, digits and hyphens.'=>'Хөдөлгүүрийн ID нь жижиг үсэг, тоо, зурааснаас бүрдсэн байх ёстой.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Zinn Digital® Ltd-ийн Гүйцэтгэх захирал Neil Lock бүтээв','Version %s'=>'Хувилбар %s','Tranzly website'=>'Tranzly вэбсайт','Zinn Digital® website'=>'Zinn Digital® вэбсайт','Settings saved.'=>'Тохиргоог хадчихав.','See the Pro plans and pricing'=>'Pro багц болон үнийг үзэх','Languages'=>'Хэлүүд','The first language is the one your content is written in. Visitors switch with the language switcher block.'=>'Эний анхдагч хэл нь таны контентын бичигдсэн хэл юм. Зочид хэл солигч блокоор дамжуулан хэлээ солино.','(default)'=>'(өгөгдмөл)','Locale code'=>'Хэлний код','For example fr_FR'=>'Тухайлбал fr_FR','Name (optional)'=>'Нэр (заавал биш)','For example Français'=>'Жишээ нь Français','Add language'=>'Хэл нэмэх','Front-end output'=>'Front-end гаралт','Class name prefix'=>'Классын нэрийн угтвар','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Нэмэлт өгөгдлийн таны хуудаснууд дээр хэвлэх ангийн нэр бүр энэ угтвараар эхлэх тул хуудсыг ямар нэмэлт өгөгдөл бүтээснийг илчлэхгүй. Үсгээр эхэлсэн, 1-ээс 8 хүртэлх жижиг үсэг эсвэл цифр байна.','Beta updates'=>'Бета шинэчлэлтүүд','This site receives beta versions as updates.'=>'Энэ сайт шинэчлэлт хэлбэрээр бета хувилбаруудыг хүлээн авдаг.','This site receives stable versions only.'=>'Энэ сайт нь зөвхөн тогтвортой хувилбаруудыг хүлээн авдаг.','Change this on the Account page'=>'Үүнийг Бүртгэлийн хуудаснаас өөрчлөх','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Бета хувилбаруудыг өөрийн бүртгэлд холбогдсон лицензтэй Pro суулгацуудад санал болгодог. Холбогдсоны дараа та Бүртгэл хуудаснаас нэгдэх боломжтой.','Save settings'=>'Тохиргоог хадгалах','Add a second language under Tranzly in the admin menu, and the switcher appears here.'=>'Админ цэс дэх Tranzly хэсгээс хоёр дахь хэлийг нэмэхэд шилжүүлэгч энд гарч ирнэ.','Switcher'=>'Шилжүүлэгч','Accessible label'=>'Хүртээмжтэй шошго','block titleLanguage switcher'=>'Хэл солигч','block descriptionLinks to this page in each of the site\'s languages. It renders nothing until two or more languages are listed.'=>'Энэ сайтын хэл тус бүрээр энэ хуудас руу холбох холбоосууд. Хоёр буюу түүнээс дээш хэл жагсаагдах хүртэл юу ч харуулахгүй.','block keywordlanguage'=>'Хэл','block keywordswitcher'=>'соlигч','block keywordtranslation'=>'орtүүлэх']];